public static Map<String, Long> countBySuffix(List<String> data) {
    return data.stream()
            .map(s -> s.substring(s.lastIndexOf('-') + 1))
            .map(String::toLowerCase)
            .collect(Collectors.groupingBy(
                    s -> s,
                    Collectors.counting()
            ));
}

