// Point.java – model wiersza CSV
public class Point {
    @CsvBindByName private double x;
    @CsvBindByName private double y;
    @CsvBindByName private double value;

    public Point() {}                       // wymagany przez OpenCSV
    public double getX() { return x; }  public void setX(double x) { this.x = x; }
    public double getY() { return y; }  public void setY(double y) { this.y = y; }
    public double getValue() { return value; }  public void setValue(double v) { this.value = v; }

    public double distanceTo(double cx, double cy) {
        return Math.hypot(x - cx, y - cy);  // sqrt((x-cx)^2 + (y-cy)^2)
    }
}

double cx = 0, cy = 1, r = 0.5;

try (Reader in = Files.newBufferedReader(Path.of("data2d.csv"));
     Writer out = Files.newBufferedWriter(Path.of("data2d_X0.0_Y1.0_D0.5.csv"))) {

    List<Point> result = new CsvToBeanBuilder<Point>(in)
            .withType(Point.class).build()
            .stream()                                           // strumień obiektów Point
            .filter(p -> p.distanceTo(cx, cy) <= r)             // wewnątrz koła
            .sorted(Comparator.comparingDouble((Point p) -> p.distanceTo(cx, cy))
                    .thenComparing(Comparator.comparingDouble(Point::getValue).reversed()))
            .toList();

    new StatefulBeanToCsvBuilder<Point>(out).build().write(result);
}
